87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        Collection<Owner> owners = this.clinicService.findAllOwners();
107	        if (owners.stream().filter(existing -> LocalDate.now().equals(existing.getRegistrationDate())).count() >= 100) {
108	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
109	        }
110	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
111	        if (owners.stream().anyMatch(existing -> existing.getTelephone().equals(owner.getTelephone()))
112	                || (!sharesHousehold && owners.stream().anyMatch(existing -> sameHousehold(existing, owner)))
113	                || owners.stream().filter(existing -> existing.getCity().equalsIgnoreCase(owner.getCity())).count() >= 50) {
114	            return new ResponseEntity<>(HttpStatus.CONFLICT);
115	        }
116	        owner.setNamesakeCount((int) owners.stream()
117	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(owner.getFirstName())
118	                && existing.getLastName().equalsIgnoreCase(owner.getLastName()))
119	            .count());
120	        owner.setCustomerCode(CustomerCode.of(owner, owners));
121	        this.clinicService.saveOwner(owner);
122	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
123	        headers.setLocation(UriComponentsBuilder.newInstance()
124	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
125	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
126	    }
