16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form, e.g. +61412345678")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "namesake_count")
61	    private Integer namesakeCount;
62	
63	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
64	    private Set<Pet> pets;
65	
66	    /** Default an absent registration date to the server's current date on first persist. */
67	    @PrePersist
68	    void defaultRegistrationDate() {
69	        if (this.registrationDate == null) {
70	            this.registrationDate = LocalDate.now();
71	        }
72	    }
73	
74	    public LocalDate getRegistrationDate() {
75	        return this.registrationDate;
76	    }
77	
78	    public void setRegistrationDate(LocalDate registrationDate) {
79	        this.registrationDate = registrationDate;
80	    }
81	
82	    public String getCustomerCode() {
83	        return this.customerCode;
84	    }
85	
86	    /** Stable identifier shared by owners of the same household (matching last name and address). */
87	    @Transient
88	    public String getHouseholdId() {
89	        return HouseholdId.of(getLastName(), this.address);
90	    }
91	
92	    public void setCustomerCode(String customerCode) {
93	        this.customerCode = customerCode;
94	    }
95	
96	    /** Membership number formatted {@code <customerCode>-M<YY>}, e.g. {@code SMI-0007-M26}. */
97	    @Transient
98	    public String getMembershipNumber() {
99	        return MembershipNumber.of(this.customerCode, this.registrationDate);
100	    }
101	
102	    public Integer getNamesakeCount() {
103	        return this.namesakeCount;
104	    }
105	
106	    public void setNamesakeCount(Integer namesakeCount) {
107	        this.namesakeCount = namesakeCount;
108	    }
109	
110	    public String getEmail() {
111	        return this.email;
112	    }
113	
114	    public void setEmail(String email) {
115	        this.email = email == null ? null : email.toLowerCase();
116	    }
117	
118	    public String getAddress() {
119	        return this.address;
120	    }
121	
122	    public void setAddress(String address) {
123	        this.address = AddressNormalizer.normalize(address);
124	    }
125	
126	    public String getCity() {
127	        return this.city;
128	    }
129	
130	    public void setCity(String city) {
131	        this.city = city;
132	    }
133	
134	    public String getTelephone() {
135	        return this.telephone;
136	    }
137	
138	    public void setTelephone(String telephone) {
139	        this.telephone = telephone == null ? null : PhoneNumbers.toE164(telephone);
140	    }
141	
142	    protected Set<Pet> getPetsInternal() {
143	        if (this.pets == null) {
144	            this.pets = new HashSet<>();
145	        }
146	        return this.pets;
147	    }
148	
149	    protected void setPetsInternal(Set<Pet> pets) {
150	        this.pets = pets;
151	    }
152	
